// A ÚNICA coisa que não existe em lugar nenhum ainda é traduzir uma
// instrução em português livre pra um diff estruturado de campos.
// A gravação em si (depois de estruturado) é 100% o gerenciar_cadastro
// que já existe no L2 — não duplicamos essa parte.
const referencia = "Campos válidos por tipo_entidade (ERPNext):\ncliente (Customer): customer_name, mobile_no, email_id, tax_id, customer_group\nproduto (Item): item_name, standard_rate (preco), description, item_group\nfornecedor (Supplier): supplier_name, mobile_no, email_id, tax_id, supplier_group";

const system_prompt = 'Você traduz uma instrução em português pra um JSON de '
  + 'campos a atualizar num ERP. Responda APENAS com um objeto JSON plano '
  + '{"campo": valor, ...}, só com os campos que a instrução realmente pede '
  + 'pra mudar, usando exatamente os nomes de campo da referência abaixo. '
  + 'Não invente campo fora da lista. Se a instrução não corresponder a nenhum '
  + 'campo conhecido, responda {}.\n\n' + referencia;

const user_prompt = 'tipo_entidade: ' + $json.tipo + '\ninstrução: ' + $json.instrucao;

// Migrado para a Lyra Central (/v1/chat) — não chama mais o Gemini direto nem
// depende de GEMINI_API_KEY. conversation_id é exigido pelo contrato do
// /v1/chat; como é uma chamada avulsa (sem conversa real no Chatwoot), usa
// o id de execução do n8n só pra rastreabilidade.
const conversation_id = 'lyra-alterar-' + $execution.id;

return [{ json: { ...$json, conversation_id, system_prompt, user_prompt } }];

function parseSSE(texto) {
  const blocos = texto.split(/\r?\n\r?\n/).filter(Boolean);
  let tokens = '';
  let functionCall = null;
  let finishReason = null;
  for (const bloco of blocos) {
    const linhas = bloco.split(/\r?\n/);
    let evento = null;
    let dadosTexto = '';
    for (const linha of linhas) {
      if (linha.startsWith('event:')) evento = linha.slice(6).trim();
      if (linha.startsWith('data:')) dadosTexto += linha.slice(5).trim();
    }
    if (!evento || !dadosTexto) continue;
    let dados;
    try { dados = JSON.parse(dadosTexto); } catch (e) { continue; }
    if (evento === 'token') tokens += (dados.text || '');
    if (evento === 'function_call') functionCall = dados;
    if (evento === 'done') finishReason = dados.finish_reason;
  }
  return { tokens, functionCall, finishReason };
}

const bruto = $input.first().json.data ?? $input.first().json.body ?? $input.first().json;
const texto = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);
const { tokens } = parseSSE(texto);

return [{ json: { texto_resposta: tokens } }];

const meta = $node['Monta Prompt de Interpretação'].json;
const texto = $input.first().json.texto_resposta || '{}';

let diff = {};
try {
  diff = JSON.parse(texto);
} catch(e) {
  throw new Error('Lyra não conseguiu interpretar a instrução');
}

if (!Object.keys(diff).length) {
  throw new Error('Nenhum campo reconhecido nessa instrução');
}

return [{
  json: {
    funcao: 'gerenciar_cadastro',
    argumentos: {
      acao: 'editar',
      tipo_entidade: meta.tipo,
      id_entidade: meta.id,
      dados_cliente: diff
    },
    _resumo_campos: Object.keys(diff).join(', ')
  }
}];

const meta = $node['Extrai Diff Estruturado'].json;
const resultadoL2 = $input.first().json;

if (!resultadoL2.sucesso) {
  return [{ json: { erro: resultadoL2.erro || 'Não foi possível salvar a alteração' } }];
}

return [{ json: { resumo: 'Campos atualizados: ' + meta._resumo_campos } }];
